            raise ValueError('Decoder graph IDs outside full native node order')
        nonself = edges[0] != edges[1]
        identity = torch.arange(nodes, device=self.device)
        source = torch.cat((edges[0, nonself], identity))
        target = torch.cat((edges[1, nonself], identity))
        degree = torch.bincount(target, minlength=nodes).to(self.data.x.dtype)
        self.decoder_support = (source, target, degree.reciprocal())
        self.synchronize()
        self.decoder_graph = {'normalization': 'incoming D^-1(A_off+I)', 'factual_offdiagonal_multiplicity': 'retained', 'identity_records': nodes, 'replaced_factual_self_records': int((~nonself).sum().item()), 'decoder_records': len(source), 'native_graph_unchanged': True, 'preparation_seconds': time.perf_counter() - start, 'support_tensor_bytes': sum((t.numel() * t.element_size() for t in self.decoder_support))}

