        torch = self.torch
        model.train()
        optimizer.zero_grad()
        queries = self.memory.common_half_query(torch, self.train_ids, self.data.y[self.train_ids], 8, generator=self.query_generator)
        self.process_counts['query_draws'] += 1
        logits, hidden = self.full_native(model, streams, bank)
        result = self.memory_read(logits, hidden, queries, 'fit')
        members = len(logits)
        native_ce = self.F.cross_entropy(logits[:, self.train_ids, :].flatten(0, 1), self.data.y[self.train_ids].repeat(members))
        retrieval_ce = self.F.nll_loss(result['retrieval_log_probs'].flatten(0, 1), self.data.y[queries].repeat(members))
        loss = native_ce + retrieval_ce
        loss.backward()
        self.process_counts['backwards'] += 1
        optimizer.step()
        self.process_counts['optimizer_steps'] += 1
        return {'total_ce': loss.item(), 'native_ce': native_ce.item(), 'retrieval_ce': retrieval_ce.item()}

