            model = wrapper if members > 1 else body
        shape = (members, 8, 8) if arm == 'shared4_graphP_privateB4' else (8, 8)
        model.register_parameter('class_decoder_B', torch.nn.Parameter(torch.zeros(shape, dtype=torch.float32, device='cpu')))
