        model.train()
        optimizer.zero_grad()
        native, scores = self.predictions(model, streams, bank)
        labels = self.data.y[self.train_ids].repeat(members)
        loss = 0.5 * self.F.cross_entropy(native[:, self.train_ids].flatten(0, 1), labels) + 0.5 * self.F.cross_entropy(scores[:, self.train_ids].flatten(0, 1), labels)
